package cn.zhuatech.cdp.controller; import cn.zhuatech.cdp.common.ApiResponse; import cn.zhuatech.cdp.dto.CdpDto.*; import cn.zhuatech.cdp.service.CdpService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('CAMPAIGN_OPERATOR','ADMIN')") public class ActivationController {private final CdpService service;public ActivationController(CdpService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
